package com.votesecure.onlinevoting.model;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="election_settings") public class ElectionSetting{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="election_name") private String electionName;private String description;@Column(name="start_time") private LocalDateTime startTime;@Column(name="end_time") private LocalDateTime endTime;private String status;
public Long getId(){return id;}public String getElectionName(){return electionName;}public void setElectionName(String x){electionName=x;}public String getDescription(){return description;}public void setDescription(String x){description=x;}public LocalDateTime getStartTime(){return startTime;}public void setStartTime(LocalDateTime x){startTime=x;}public LocalDateTime getEndTime(){return endTime;}public void setEndTime(LocalDateTime x){endTime=x;}public String getStatus(){return status;}public void setStatus(String x){status=x;}}
